{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "주어진 하중 조건에서 감속기 축의 주요 치수를 결정한 이유를 확인한다. 축 지름 선정 이유가 하중에 따른 기계적 요구와 연결되는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "교재에 주어진 하중 조건으로 감속기 축 지름과 베어링을 선정한 개인 과제 상황.",
          "task": "주어진 하중을 견디며 요구 기능을 수행할 수 있는 축 지름을 결정하는 것.",
          "action": "축에 전달되는 하중과 그에 따른 응력 또는 변형을 근거로 지름 선정 이유를 설명한다.",
          "result": "선정한 지름이 해당 하중 조건에서 적절하다고 판단한 계산상 근거나 설계상 여유가 드러난다. 실제 제작이나 시험 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "감속기 축 지름을 정한 결정적인 이유",
          "주어진 하중이 축에 전달되어 굽힘이나 비틀림 등으로 작용하는 방식과 선정 이유의 연결",
          "선정 이유를 뒷받침하는 계산 결과, 허용 수준 또는 설계상 제약"
        ]
      },
      "question": "교재에 주어진 하중 조건으로 축 지름과 베어링을 선정하셨던데요, 그때 감속기 축의 지름을 정한 결정적인 이유는 무엇이었어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "축 지름을 결정한 핵심 이유를 명확히 밝히고, 축에 전달되는 하중과 발생하는 응력 또는 변형에 연결한다.",
            "계산 결과나 허용 수준 등 구체적인 근거로 선정한 지름의 타당성을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "하중이나 강도 등 축 지름 선정에 관련된 이유를 제시한다.",
            "선정 이유는 타당하지만 실제 하중의 작용 방식이나 계산 근거에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "선정한 지름이나 사용한 공식만 언급하고 지름을 결정한 이유를 설명하지 못한다.",
            "제시한 이유가 주어진 하중 조건과 연결되지 않거나 기계적으로 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "3D 모델을 양산 도면으로 전환할 때 기능에 필요한 치수 공차를 지정할 수 있는지 확인한다. 베어링 끼워맞춤부의 기능에 맞는 공차 지정에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "감속기 베어링 하우징의 3D 모델을 양산용 2D 도면으로 정리하는 상황.",
          "task": "베어링 끼워맞춤부에 제작자가 해석할 수 있는 치수 공차를 지정하는 것.",
          "action": "필요한 끼워맞춤 조건을 가정하고, 베어링과 하우징의 결합 기능에 맞는 공차 등급이나 허용 치수 범위를 제안한다.",
          "result": "필요한 결합 기능을 확보하면서 불필요하게 엄격하지 않은 공차가 도면에 명확히 표현되는 예상 결과를 설명한다."
        },
        "expectedEvidence": [
          "베어링 끼워맞춤부에 지정할 치수 공차의 구체적인 표기 또는 허용 범위 설정 방식",
          "제안한 공차와 베어링 고정 또는 조립에 필요한 끼워맞춤 조건의 연결",
          "가공 부담을 불필요하게 높이지 않으면서 필요한 기능을 확보하도록 공차 범위를 정한 이유"
        ]
      },
      "question": "감속기 베어링 하우징의 3D 모델을 양산 도면으로 옮기는 상황이라고 해 볼게요. 그때 베어링 끼워맞춤부의 치수 공차는 어떻게 지정하시겠어요?",
      "answerTip": "상황을 떠올리며 생각을 차분히 풀어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가정한 끼워맞춤 조건에 적합한 공차 등급이나 허용 치수 범위 설정 방식을 제작자가 해석할 수 있도록 제시한다.",
            "공차 지정이 베어링의 결합 기능에 부합하며, 필요한 범위보다 과도하게 공차를 좁히지 않는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "베어링 끼워맞춤 기능과 연결되는 공차 지정 방향을 제시한다.",
            "지정 방향은 타당하지만 구체적인 표기나 허용 범위 설정 방식, 가공 부담에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "공차를 좁히겠다는 일반적인 언급에 그치거나 실제 도면에 적용할 지정 방식을 제시하지 못한다.",
            "제안한 공차가 끼워맞춤 기능과 연결되지 않거나 조립을 방해하는 등 기술적으로 타당하지 않다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P14",
  "interviews": [
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "양산 준비를 위한 설비 배치 판단을 검증한다. 본인이 작성한 배치안에서 설비 위치를 정할 때 가장 중요하게 적용한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "신규 차종 도어 트림 조립 라인의 배치안을 작성하던 상황과 당시의 생산 조건이 제시된다.",
          "task": "본인이 검토한 범위에서 설비 위치를 정해야 했던 과제가 드러난다.",
          "action": "설비 위치 선정에 가장 중요하게 적용한 기준 하나를 밝히고, 해당 기준을 실제 배치에 적용한 내용을 설명한다.",
          "result": "그 기준이 반영된 배치의 모습이나 기대했던 생산상 효과가 제시된다. 별도의 양산 성과 수치는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "설비 위치를 정할 때 가장 중요하게 적용한 기준 하나",
          "해당 기준을 우선한 이유를 뒷받침하는 당시의 공정 조건",
          "그 기준이 실제 설비 위치에 반영된 구체적인 내용",
          "선택한 배치가 작업자 동선이나 생산 흐름에 미칠 영향에 대한 설명"
        ]
      },
      "question": "신규 차종 도어 트림 조립 라인 양산 준비에서 라인 배치안을 작성하셨던데요, 그때 설비 위치를 정한 기준 중 가장 중요했던 것은 무엇이었어요?",
      "answerTip": "기억나는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가장 중요하게 적용한 배치 기준 하나를 명확히 제시한다.",
            "당시 공정 조건을 근거로 그 기준을 우선한 이유를 구체적으로 설명한다.",
            "기준이 반영된 설비 위치와 그 배치가 생산 흐름에 미칠 영향을 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "설비 위치 선정에 적용한 기준이 확인되고 직무 상황에도 대체로 타당하다.",
            "기준을 우선한 이유, 실제 배치에 적용한 내용, 예상 영향 중 일부의 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "설비 위치를 정한 기준을 밝히지 못하거나 일반적인 배치 원칙만 나열한다.",
            "제시한 기준과 실제 배치 사이의 연결이 드러나지 않거나 당시 공정 조건과 맞지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "작업자가 그대로 따를 수 있는 작업 표준서 작성 행동을 검증한다. 실제 작성한 작업 순서 한 단계를 실행 가능한 문장으로 표현한 방식에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "도람화성에서 시생산 2회에서 나온 조립 문제를 반영해 작업 표준서 초판을 작성하던 상황이 제시된다.",
          "task": "조립 작업 순서 중 한 단계를 작업자가 읽고 실행할 수 있도록 작성해야 했던 과제가 드러난다.",
          "action": "본인이 표준서에 작성한 한 단계의 문장을 제시하고, 그 문장이 가리키는 실제 작업을 설명한다.",
          "result": "제시한 문장으로 작업 대상과 수행 행동을 식별할 수 있어 실행상의 모호함이 줄어드는 점이 드러난다. 별도의 현장 적용 성과는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "실제 작성한 작업 순서 한 단계에 해당하는 문장",
          "문장에 나타난 구체적인 작업 대상과 수행 행동",
          "해당 문구가 당시 조립 작업에 맞는다는 맥락",
          "작업자가 문장을 읽고 실행할 내용을 분명하게 알 수 있는 표현"
        ]
      },
      "question": "도람화성에서 시생산 2회에서 나온 조립 문제를 반영해 작업 표준서 초판을 작성하셨던데요, 그때 작업 순서 한 단계를 표준서에 어떤 문장으로 적으셨어요?",
      "answerTip": "당시 내용을 떠올려 본인 말로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "본인이 작성한 작업 순서 한 단계를 구체적인 문장으로 제시한다.",
            "작업 대상과 수행 행동이 명확하고 당시 조립 작업의 맥락에 맞는다.",
            "작업자가 무엇을 해야 하는지 추가 해석 없이 알 수 있는 표현이다."
          ]
        },
        "acceptable": {
          "criteria": [
            "작성한 문장에서 작업 대상과 수행 행동을 대체로 파악할 수 있다.",
            "일부 표현이 포괄적이거나 작업 맥락에 대한 설명이 부족해 실행 내용을 이해하는 데 추가 확인이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "실제로 작성한 작업 단계의 문장을 제시하지 않고 표준서의 목차나 작성 원칙만 설명한다.",
            "문장이 추상적이거나 작업 대상과 수행 행동이 불분명해 작업자가 실행할 내용을 파악하기 어렵다."
          ]
        }
      }
    }
  ]
}
